import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { listSponsors } from '../../common/sponsors';
/**
 * Managers pick the sponsor presenting a giveaway or calendar. Option values
 * are strings ("s12") so the browser keeps "No sponsor" first.
 */
export default class SponsorSelect extends Component {
  sponsors = null;
  oninit(vnode) {
    super.oninit(vnode);
    listSponsors().then(list => this.sponsors = list).catch(() => this.sponsors = []).finally(() => m.redraw());
  }
  view() {
    const t = key => app.translator.trans(`ernestdefoe-giveaways.forum.sponsors.${key}`);
    const list = this.sponsors;
    if (!list || !list.length && !this.attrs.value) return null;
    return m("div", {
      className: "Form-group SponsorSelect"
    }, m("label", null, t('select_label')), m("select", {
      className: "FormControl",
      value: this.attrs.value ? `s${this.attrs.value}` : '',
      onchange: e => {
        const v = e.target.value;
        this.attrs.onchange(v ? parseInt(v.slice(1), 10) : null);
      }
    }, m("option", {
      value: ""
    }, t('select_none')), list.map(s => m("option", {
      value: `s${s.id}`
    }, s.name))), m("p", {
      className: "helpText"
    }, t('select_help')));
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/sponsors/SponsorSelect', SponsorSelect);